function LogoUploadButton({ small }) {
  const { setLogo } = useContext(LogoContext);
  const inputRef = React.useRef(null);

  const handleFile = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => setLogo(reader.result);
    reader.readAsDataURL(file);
  };

  return (
    <>
      <input ref={inputRef} type="file" accept="image/*" onChange={handleFile} style={{ display: "none" }} />
      <button
        onClick={() => inputRef.current?.click()}
        style={{
          display: "flex", alignItems: "center", gap: 6, background: "transparent",
          border: `1px dashed rgba(255,255,255,0.35)`, color: "#fff", opacity: 0.85,
          cursor: "pointer", fontSize: small ? 11 : 12.5, padding: small ? "4px 8px" : "6px 10px",
          borderRadius: 7,
        }}
      >
        <Upload size={12} /> {small ? "Cambiar logo" : "Subir logo"}
      </button>
    </>
  );
}

// Recuerda la pestaña / menú / vista donde estaba el usuario, para que al
// REFRESCAR la página vuelva exactamente ahí (se guarda por pestaña del
// navegador, en sessionStorage).
function useEstadoRecordado(clave, inicial) {
  const k = "vista:" + clave;
  const [valor, setValor] = useState(() => {
    try {
      const g = sessionStorage.getItem(k);
      if (g !== null) return JSON.parse(g);
    } catch (e) {}
    return typeof inicial === "function" ? inicial() : inicial;
  });
  useEffect(() => {
    try { sessionStorage.setItem(k, JSON.stringify(valor)); } catch (e) {}
  }, [k, valor]);
  return [valor, setValor];
}

// "App de clientes": cuando la página se abre desde /cliente.html (la que
// usa el APK de clientes), la app entra en modo cliente — login propio,
// solo acepta usuarios categoría "cliente" y guarda su sesión aparte.
const MODO_CLIENTE = typeof window !== "undefined" && !!window.__MODO_CLIENTE__;
const CLAVE_SESION = MODO_CLIENTE ? "sesion_cliente" : "sesion_usuario";
// Un cliente puede tener uno o varios sitios asignados; se guardan en
// usuarios.area separados por "|" (ej. "Hotel Belén|Hotel Escazú").
const SEP_SITIOS = "|";
const sitiosDeTexto = (t) => String(t || "").split(SEP_SITIOS).map((x) => x.trim()).filter(Boolean);
// Dentro del APK (WebView de Android) no hay ventanas nuevas ni descargas de
// archivos: el CSV se oculta ahí, y para imprimir/PDF se usa el puente nativo
// de la APK v2 (window.SalvavidasAndroid, ver abrirImpresion).
const EN_APK = typeof navigator !== "undefined" && /SalvavidasAPK/.test(navigator.userAgent || "");

// ---- Imprimir / guardar PDF en PC, celular (navegador) y APK ----
// La APK nueva (v2) trae el puente window.SalvavidasAndroid, que abre el
// diálogo de impresión de Android (ahí se elige impresora o "Guardar como
// PDF"). En la PC y en el navegador del celular se usa la ventana nueva +
// window.print() de siempre.
const puenteAndroid = () => {
  try {
    const p = typeof window !== "undefined" ? window.SalvavidasAndroid : null;
    return p && typeof p.imprimir === "function" ? p : null;
  } catch { return null; }
};
const AVISO_APK_VIEJA = "Para guardar los reportes en PDF desde el celular hay que instalar la versión nueva de la app (Monitoreo_Salvavidas.apk versión 4). Pídasela al administrador.";
const quitarAutoImpresion = (html) => String(html || "").replace(/<script>\s*setTimeout\(function\(\)\{\s*window\.print\(\);\s*\},\s*\d+\);\s*<\\?\/script>/g, "");
// ---- Papel membretado de Salvavidas para todos los reportes impresos ----
// Primera página: datos de la empresa + logo + marca de agua (rociador).
// Todas las páginas: logo arriba a la derecha y pie con web, banderas y QR.
const MEMBRETE_IMG = {"logo": "data:image/png;base64,", "qr": "data:image/png;base64,", "banderas": "data:image/png;base64,", "marca": "data:image/png;base64,"};
