// El estado "Vencido" se calcula automáticamente: si el curso no está
// Cancelado ni Realizado y su fecha de vencimiento ya pasó, se muestra
// como Vencido (rojo) sin que nadie tenga que cambiarlo manualmente.
function estadoEfectivoCurso(r) {
  if (r.estado === "Cancelado") return r.estado;
  const venc = vencimientoCalculado(r.fecha);
  if (venc && venc < todayISO()) return "Vencido";
  return r.estado;
}

// El vencimiento de un curso EHS es dinámico: vence exactamente 1 año
// después de la fecha en que se realizó/coordinó. Al "renovar" (cambiar
// la fecha del curso), el vencimiento y el estado Vencido se recalculan solos.
function vencimientoCalculado(fecha) {
  if (!fecha) return null;
  const d = new Date(fecha + "T00:00:00");
  d.setFullYear(d.getFullYear() + 1);
  return d.toISOString().slice(0, 10);
}

// Estado efectivo de una OD (Inspecciones/Proyectos): si el registro está
// "Activo" y la fecha de control (vencimiento en Inspecciones, o fecha de
// entrega en Proyectos) ya pasó, se muestra automáticamente como "Vencido"
// (rojo) sin que nadie tenga que cambiarlo a mano. "No Activo" y
// "Entregado" no se ven afectados por esta regla.
function estadoEfectivoOD(r, campoFecha) {
  const fecha = r[campoFecha];
  if (r.estado === "Activo" && fecha && fecha < todayISO()) return "Vencido";
  return r.estado;
}

/* ---------------------------------------------------------
   SEED DATA
   --------------------------------------------------------- */
const FRECUENCIA_OPCIONES = ["Semanal", "Mensual", "Bimensual", "Trimestral", "Cuatrimestral", "Semestral", "Anual"];

// Facturación de IPM: a diferencia de OD Correctivos (que se factura al
// cerrar el trabajo), un IPM se factura una y otra vez según su
// periodicidad. Esto traduce cada frecuencia a meses (Semanal se trata
// como ~1 semana) para calcular la siguiente fecha de factura.
const FRECUENCIA_A_MESES = { "Semanal": 0, "Mensual": 1, "Bimensual": 2, "Trimestral": 3, "Cuatrimestral": 4, "Semestral": 6, "Anual": 12 };
function sumarIntervaloFrecuencia(fechaISO, frecuencia) {
  const base = fechaISO ? new Date(fechaISO + "T00:00:00") : new Date();
  if (frecuencia === "Semanal") {
    base.setDate(base.getDate() + 7);
  } else {
    const meses = FRECUENCIA_A_MESES[frecuencia] ?? 1;
    base.setMonth(base.getMonth() + meses);
  }
  return base.toISOString().slice(0, 10);
}
function sumarDiasISO(fechaISO, dias) {
  const base = fechaISO ? new Date(fechaISO + "T00:00:00") : new Date();
  base.setDate(base.getDate() + dias);
  return base.toISOString().slice(0, 10);
}

const MESES_ABREV = ["Ene", "Feb", "Mar", "Abr", "May", "Jun", "Jul", "Ago", "Set", "Oct", "Nov", "Dic"];

// Cada entrada de la agenda es una clave "AAAA-MM" (ej. "2026-11") — así
// una OD puede tener meses marcados de este año y del que viene sin que se
// mezclen ni se repitan solos año tras año.
function claveMesAno(anio, mesIdx) { return `${anio}-${String(mesIdx + 1).padStart(2, "0")}`; }
function esClaveMesAnoValida(m) { return /^\d{4}-\d{2}$/.test(m); }
function formatMesAno(clave) {
  const [anio, mes] = clave.split("-");
  const idx = parseInt(mes, 10) - 1;
  return `${MESES_ABREV[idx] || "?"} ${anio.slice(2)}`;
}
function mesesValidosOrdenados(mesesVisita) {
  return (Array.isArray(mesesVisita) ? mesesVisita : []).filter(esClaveMesAnoValida).sort();
}

// Devuelve el próximo mes de la agenda de visitas después de hoy (cada
// entrada ya trae su año, así que no hay que "dar la vuelta" al terminar el
// año) — solo para mostrar, no dispara nada por sí solo.
function proximoMesEnAgenda(mesesVisita, hoy) {
  const ordenados = mesesValidosOrdenados(mesesVisita);
  if (ordenados.length === 0) return "";
  const mesActual = hoy.slice(0, 7);
  const siguiente = ordenados.find((m) => m > mesActual);
  return siguiente ? formatMesAno(siguiente) : "";
}

// Estado de facturación de una OD de IPM. Si la OD tiene una agenda de
// meses de visita marcada (Nov 26, Feb 27...), esa agenda manda: se
// considera pendiente si el mes calendario actual está en la lista y
// todavía no se marcó facturado este mes. Si no tiene agenda, se usa el
// mecanismo anterior de frecuencia + próxima fecha calculada sola.
function estadoFacturacionIpm(r, hoy) {
  const meses = mesesValidosOrdenados(r.mesesVisita);
  const usaAgenda = meses.length > 0;
  if (usaAgenda) {
    const mesActual = hoy.slice(0, 7);
    const tocaEsteMes = meses.includes(mesActual);
    const yaFacturadoEsteMes = !!r.ultimaFacturaIpm && r.ultimaFacturaIpm.slice(0, 7) === mesActual;
    const pendiente = tocaEsteMes && !yaFacturadoEsteMes;
    const proximo = proximoMesEnAgenda(meses, hoy);
    return {
      pendiente,
      atrasada: false,
      etiqueta: pendiente ? `Toca este mes (${formatMesAno(mesActual)})` : yaFacturadoEsteMes ? "Facturado este mes" : (proximo ? `Próxima visita: ${proximo}` : "Sin más fechas en la agenda"),
      colorTxt: pendiente ? T.amber : yaFacturadoEsteMes ? T.green : T.gray,
      colorFondo: pendiente ? T.amberSoft : yaFacturadoEsteMes ? T.greenSoft : T.graySoft,
    };
  }
  const tieneProxima = !!r.proximaFacturaIpm;
  const atrasada = tieneProxima && r.proximaFacturaIpm < hoy;
  const proximaSemana = tieneProxima && !atrasada && r.proximaFacturaIpm <= sumarDiasISO(hoy, 7);
  return {
    pendiente: !tieneProxima || r.proximaFacturaIpm <= hoy,
    atrasada,
    etiqueta: tieneProxima ? (atrasada ? `Atrasada desde ${r.proximaFacturaIpm}` : `Próxima: ${r.proximaFacturaIpm}`) : "Sin programar",
    colorTxt: atrasada ? T.red : proximaSemana ? T.amber : tieneProxima ? T.green : T.gray,
    colorFondo: atrasada ? T.redSoft : proximaSemana ? T.amberSoft : tieneProxima ? T.greenSoft : T.graySoft,
  };
}

// Clave (comparable como texto) para ordenar OD de IPM de la más próxima a
// facturar/visitar a la más lejana: la del mes que se está cursando queda
// arriba de todo, y las de meses futuros van más abajo mientras más lejos
// estén. Las atrasadas (fecha ya pasada) ordenan antes que el mes actual,
// y las que no tienen nada programado quedan al final.
function claveOrdenamientoIpm(r, hoy) {
  const meses = mesesValidosOrdenados(r.mesesVisita);
  if (meses.length > 0) {
    const mesActual = hoy.slice(0, 7);
    const yaFacturadoEsteMes = !!r.ultimaFacturaIpm && r.ultimaFacturaIpm.slice(0, 7) === mesActual;
    if (meses.includes(mesActual) && !yaFacturadoEsteMes) return mesActual + "-01";
    const siguiente = meses.find((m) => m > mesActual);
    return siguiente ? siguiente + "-01" : "9999-12-31";
  }
  return r.proximaFacturaIpm || "9999-12-31";
}

// Contenedor de gráfica que NO se aprieta en pantallas angostas: si no cabe,
// aparece una barra para correrla de izquierda a derecha. Arranca mostrando
// el final (las quincenas más recientes).
function GraficaDesplazable({ minWidth, innerRef, children }) {
  const cajaRef = React.useRef(null);
  useEffect(() => {
    const c = cajaRef.current;
    if (c) c.scrollLeft = c.scrollWidth;
  }, [minWidth]);
  return (
    <div ref={cajaRef} style={{ overflowX: "auto", WebkitOverflowScrolling: "touch", paddingBottom: 4 }}>
      <div ref={innerRef} style={{ minWidth }}>{children}</div>
    </div>
  );
}

// Mes siguiente a una clave "AAAA-MM" (para rangos de fechas en consultas).
function claveMesSiguiente(clave) {
  const [a, m] = clave.split("-").map(Number);
  return m === 12 ? `${a + 1}-01` : `${a}-${String(m + 1).padStart(2, "0")}`;
}

// Nota de una OD en una sola línea; al tocarla se agranda para escribir.
function NotaCompactaOD({ valor, onChange }) {
  const [foco, setFoco] = useState(false);
  return (
    <textarea
      rows={foco ? 4 : 1}
      onFocus={() => setFoco(true)}
      onBlur={() => setFoco(false)}
      style={{ ...inputStyle, fontSize: 12, padding: "6px 9px", width: foco ? 240 : 170, minHeight: 0, resize: "none", fontFamily: "inherit", whiteSpace: foco ? "pre-wrap" : "nowrap", overflow: "hidden", textOverflow: "ellipsis", transition: "width .15s" }}
      placeholder="Notas..."
      value={valor || ""}
      onChange={(e) => onChange(e.target.value)}
    />
  );
}

// Fechas de visita / facturación de una OD de IPM (vista optimizada):
// solo se ven las fechas que se agregaron, cada una con su color de estado.
// "+ Agregar fecha" abre una pestaña con el año y los 12 meses para ir
// agregando una por una. Tocar una fecha la marca (o desmarca) facturada.
function AgendaFechasIpm({ row, puedeAgendar, puedeFacturar, mesesFacturados, onToggleMes, onFacturar, onFacturarAtrasadas, onDesfacturar }) {
  const hoy = todayISO();
  const mesActual = hoy.slice(0, 7);
  const fechas = mesesValidosOrdenados(row.mesesVisita);
  const [abierto, setAbierto] = useState(false);
  const [pos, setPos] = useState({ top: 0, left: 0 });
  const [anioVista, setAnioVista] = useState(new Date().getFullYear());
  const botonRef = React.useRef(null);
  const popRef = React.useRef(null);

  useEffect(() => {
    if (!abierto) return;
    const fuera = (e) => {
      if (popRef.current?.contains(e.target) || botonRef.current?.contains(e.target)) return;
      setAbierto(false);
    };
    const cerrar = () => setAbierto(false);
    document.addEventListener("mousedown", fuera);
    document.addEventListener("touchstart", fuera);
    window.addEventListener("resize", cerrar);
    window.addEventListener("scroll", cerrar, true);
    return () => {
      document.removeEventListener("mousedown", fuera);
      document.removeEventListener("touchstart", fuera);
      window.removeEventListener("resize", cerrar);
      window.removeEventListener("scroll", cerrar, true);
    };
  }, [abierto]);

  const abrir = () => {
    if (abierto) { setAbierto(false); return; }
    const r = botonRef.current?.getBoundingClientRect();
    if (r) {
      const ancho = 250;
      const left = Math.max(8, Math.min(r.left, window.innerWidth - ancho - 8));
      const altoAprox = 250;
      const top = r.bottom + 8 + altoAprox > window.innerHeight ? Math.max(8, r.top - altoAprox - 8) : r.bottom + 8;
      setPos({ top, left });
    }
    setAbierto(true);
  };

  const estadoDe = (clave) => {
    if (mesesFacturados.has(clave)) return "fact";
    if (clave === mesActual) return "toca";
    if (clave < mesActual) return "venc";
    return "prog";
  };
  const ESTILO = {
    fact: { background: T.greenSoft, color: T.green, border: `1.5px solid ${T.green}55` },
    toca: { background: T.accent, color: "#fff", border: `1.5px solid ${T.accent}`, boxShadow: `0 0 0 3px ${T.accentSoft}` },
    venc: { background: T.redSoft, color: T.red, border: `1.5px solid ${T.red}55` },
    prog: { background: "#fff", color: T.accent, border: `1.5px solid ${T.accent}88` },
  };
  const TITULO = { fact: "Facturada", toca: "Toca este mes", venc: "Atrasada: no se ha marcado facturada", prog: "Pendiente: todavía no toca" };

  const tocarFecha = (clave) => {
    if (!puedeFacturar) return;
    const e = estadoDe(clave);
    if (e === "fact") onDesfacturar(row, clave);
    else if (e !== "prog") onFacturar(row, clave);
  };

  const nFact = fechas.filter((f) => estadoDe(f) === "fact").length;
  const nVenc = fechas.filter((f) => estadoDe(f) === "venc").length;
  const tocaHoy = fechas.includes(mesActual) && !mesesFacturados.has(mesActual);

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 5, minWidth: 250, maxWidth: 340 }}>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 5, alignItems: "center" }}>
        {fechas.map((clave) => {
          const e = estadoDe(clave);
          return (
            <span
              key={clave}
              onClick={() => tocarFecha(clave)}
              title={TITULO[e] + (puedeFacturar && e !== "prog" ? (e === "fact" ? " — toque para quitar la marca" : " — toque para marcarla facturada") : "")}
              style={{ ...ESTILO[e], borderRadius: 7, fontSize: 11.5, fontWeight: 700, padding: "3px 8px", display: "inline-flex", alignItems: "center", gap: 5, cursor: puedeFacturar && e !== "prog" ? "pointer" : "default", whiteSpace: "nowrap" }}
            >
              {e === "fact" ? "✓ " : e === "venc" ? "! " : ""}{formatMesAno(clave)}
              {puedeAgendar && (
                <span
                  onClick={(ev) => { ev.stopPropagation(); onToggleMes(row.id, clave); }}
                  title="Quitar esta fecha"
                  style={{ fontWeight: 400, opacity: 0.6, fontSize: 11, cursor: "pointer", padding: "0 1px" }}
                >✕</span>
              )}
            </span>
          );
        })}
        {puedeAgendar && (
          <button
            ref={botonRef}
            type="button"
            onClick={abrir}
            style={{ border: `1.5px dashed ${abierto ? T.accent : "#cbd5e1"}`, background: abierto ? T.accentSoft : "#f8fafc", color: abierto ? T.accent : T.inkSoft, borderRadius: 7, fontSize: 11.5, fontWeight: 700, padding: "3px 9px", cursor: "pointer", fontFamily: "inherit" }}
          >+ Agregar fecha</button>
        )}
        {!puedeAgendar && fechas.length === 0 && <span style={{ color: T.gray, fontSize: 12 }}>Sin fechas</span>}
      </div>
      {fechas.length > 0 && (
        <div style={{ fontSize: 11, color: T.gray, display: "flex", gap: 6, alignItems: "center", flexWrap: "wrap" }}>
          {puedeFacturar && <span style={{ width: "100%", fontSize: 10.5 }}>Toque una fecha para marcarla facturada (o para quitar la marca).</span>}
          <span>{nFact} de {fechas.length} facturada{fechas.length === 1 ? "" : "s"}</span>
          {nVenc > 0 && <span style={{ color: T.red, fontWeight: 600 }}>· {nVenc} atrasada{nVenc === 1 ? "" : "s"}</span>}
          {nVenc > 0 && puedeFacturar && (
            <button type="button" onClick={() => onFacturarAtrasadas(row, fechas.filter((f) => estadoDe(f) === "venc"))} style={{ border: `1px solid ${T.green}`, background: T.greenSoft, color: T.green, borderRadius: 7, fontSize: 11.5, fontWeight: 700, padding: "3px 9px", cursor: "pointer", fontFamily: "inherit" }}>
              ✓ Marcar atrasadas como facturadas
            </button>
          )}
          {tocaHoy ? (
            puedeFacturar ? (
              <button type="button" onClick={() => onFacturar(row, mesActual)} style={{ border: "none", background: T.accent, color: "#fff", borderRadius: 7, fontSize: 11.5, fontWeight: 700, padding: "3px 9px", cursor: "pointer", fontFamily: "inherit" }}>
                ✓ Facturar {formatMesAno(mesActual).split(" ")[0]}
              </button>
            ) : <span style={{ color: T.accent, fontWeight: 700 }}>· toca {formatMesAno(mesActual).split(" ")[0]}</span>
          ) : nVenc === 0 && <span style={{ color: T.green, fontWeight: 600 }}>· al día</span>}
        </div>
      )}
      {abierto && (
        <div ref={popRef} style={{ position: "fixed", top: pos.top, left: pos.left, width: 250, background: "#fff", border: `1px solid ${T.line}`, borderRadius: 12, boxShadow: "0 12px 40px rgba(0,0,0,.18)", padding: 14, zIndex: 3000 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
            <button type="button" onClick={() => setAnioVista((a) => a - 1)} style={{ border: "none", background: T.graySoft, borderRadius: 7, width: 30, height: 28, cursor: "pointer", color: T.inkSoft, fontSize: 14 }}>‹</button>
            <span style={{ fontWeight: 800, fontSize: 14, color: T.ink }}>{anioVista}</span>
            <button type="button" onClick={() => setAnioVista((a) => a + 1)} style={{ border: "none", background: T.graySoft, borderRadius: 7, width: 30, height: 28, cursor: "pointer", color: T.inkSoft, fontSize: 14 }}>›</button>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 6 }}>
            {MESES_ABREV.map((mes, i) => {
              const clave = claveMesAno(anioVista, i);
              const ya = fechas.includes(clave);
              const esHoy = clave === mesActual;
              return (
                <button
                  key={clave}
                  type="button"
                  onClick={() => onToggleMes(row.id, clave)}
                  title={ya ? `Quitar ${mes} ${anioVista}` : `Agregar ${mes} ${anioVista}`}
                  style={{
                    border: `1px solid ${ya ? T.accent : esHoy ? T.accent + "66" : T.line}`, borderRadius: 8, padding: "8px 0", cursor: "pointer", fontSize: 12.5, fontWeight: 700, fontFamily: "inherit",
                    background: ya ? T.accent : "#fff", color: ya ? "#fff" : T.ink,
                  }}
                >{mes}</button>
              );
            })}
          </div>
          <div style={{ fontSize: 11, color: T.gray, marginTop: 10, lineHeight: 1.4 }}>
            Toque un mes para agregarlo (o quitarlo). Puede agregar varias, una por una; se cierra al tocar afuera. <b style={{ color: T.accent }}>Naranja</b> = ya agregada.
          </div>
        </div>
      )}
    </div>
  );
}

// Selector de la agenda de meses de visita de una OD de IPM. Tiene su
// propio año "en pantalla" (por defecto el actual) para poder marcar meses
// de este año o del siguiente sin que se mezclen — lo marcado se guarda
// siempre con su año (claveMesAno), así que cambiar de año aquí solo
// cambia qué grilla de meses se ve, nunca borra lo ya marcado.
function AgendaMesesIpm({ row, isAdmin, onToggle }) {
  const [anioVista, setAnioVista] = useState(new Date().getFullYear());
  const seleccionados = mesesValidosOrdenados(row.mesesVisita);
  if (!isAdmin) {
    return seleccionados.length === 0 ? (
      <span style={{ color: T.gray, fontSize: 12 }}>—</span>
    ) : (
      <div style={{ display: "flex", flexWrap: "wrap", gap: 3, maxWidth: 150 }}>
        {seleccionados.map((m) => <Badge key={m} color={T.accent} soft={T.blueSoft}>{formatMesAno(m)}</Badge>)}
      </div>
    );
  }
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 4, maxWidth: 175 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
        <button type="button" onClick={() => setAnioVista((a) => a - 1)} style={{ border: "none", background: T.graySoft, borderRadius: 5, cursor: "pointer", fontSize: 11, padding: "2px 6px", color: T.gray }}>‹</button>
        <span style={{ fontSize: 11.5, fontWeight: 700, color: T.inkSoft }}>{anioVista}</span>
        <button type="button" onClick={() => setAnioVista((a) => a + 1)} style={{ border: "none", background: T.graySoft, borderRadius: 5, cursor: "pointer", fontSize: 11, padding: "2px 6px", color: T.gray }}>›</button>
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 3 }}>
        {MESES_ABREV.map((mes, i) => {
          const clave = claveMesAno(anioVista, i);
          const activo = seleccionados.includes(clave);
          return (
            <button
              key={clave}
              type="button"
              onClick={() => onToggle(row.id, clave)}
              style={{
                border: "none", borderRadius: 5, cursor: "pointer", fontSize: 10.5, fontWeight: 700,
                padding: "3px 5px", background: activo ? T.accent : T.graySoft, color: activo ? "#fff" : T.gray,
              }}
              title={activo ? `Quitar ${mes} ${anioVista} de la agenda` : `Agregar ${mes} ${anioVista} a la agenda`}
            >
              {mes}
            </button>
          );
        })}
      </div>
      {seleccionados.length > 0 && (
        <div style={{ display: "flex", flexWrap: "wrap", gap: 3 }}>
          {seleccionados.map((m) => (
            <span
              key={m}
              onClick={() => onToggle(row.id, m)}
              title="Quitar de la agenda"
              style={{ cursor: "pointer", fontSize: 10, fontWeight: 700, padding: "2px 6px", borderRadius: 999, background: T.blueSoft, color: T.blue }}
            >
              {formatMesAno(m)} ✕
            </span>
          ))}
        </div>
      )}
    </div>
  );
}

// Normaliza un valor de frecuencia importado desde Excel (espacios de más,
// mayúsculas distintas, etc.) para que coincida exactamente con una de las
// opciones válidas — si no, el desplegable de edición del admin se vería
// vacío aunque el asistente sí viera el texto tal cual.
function normalizarFrecuencia(valor) {
  if (!valor) return "";
  const limpio = String(valor).trim();
  const encontrada = FRECUENCIA_OPCIONES.find((f) => f.toLowerCase() === limpio.toLowerCase());
  return encontrada || limpio;
}

