// Lista, ordenada por atraso, las OD de IPM que corresponde facturar este
// mes (atrasadas de meses anteriores + las que vencen dentro del mes
// calendario actual) — así no se olvida facturar trabajo recurrente que no
// depende de cerrar la OD, a diferencia de Correctivos. Se recalcula sola
// cada mes (se basa en la fecha de hoy, no en una lista fija), y en cuanto
// se marca "Facturado" la fila desaparece de aquí porque su próxima fecha
// pasa a caer en un mes futuro.
function FacturacionIpmCard() {
  const [rows, setRows] = useClientesArea("inspecciones");
  const currentUser = useContext(CurrentUserContext);
  const confirmar = useContext(ConfirmContext);
  const puedeMarcar = currentUser?.categoria === "admin" || currentUser?.categoria === "asistente";
  const [busqueda, setBusqueda] = useState("");
  const hoy = todayISO();
  const pendientesDelMes = rows
    .filter((r) => (r.tipoOD || "Normal") === "Normal" && r.estado === "Activo")
    .filter((r) => {
      // Solo entran a "este mes" las OD que tienen agenda de meses de visita
      // (marcada en "Acción") y ese mes en curso está en su agenda y aún no
      // se marcó facturado. Las que no tienen agenda quedan fuera de esta
      // lista hasta que se les configure, en vez de aparecer todos los
      // meses como "Sin programar".
      const usaAgenda = Array.isArray(r.mesesVisita) && r.mesesVisita.length > 0;
      if (!usaAgenda) return false;
      return estadoFacturacionIpm(r, hoy).pendiente;
    })
    .sort((a, b) => {
      // De la más próxima (atrasadas y el mes actual, arriba) a la más
      // lejana. Se recalcula en cada render, así se reacomoda sola en
      // cuanto cambia el mes o se marca algo facturado.
      const claveA = claveOrdenamientoIpm(a, hoy);
      const claveB = claveOrdenamientoIpm(b, hoy);
      if (claveA !== claveB) return claveA.localeCompare(claveB);
      return (a.od || "").localeCompare(b.od || "");
    });
  const atrasadas = pendientesDelMes.filter((r) => r.proximaFacturaIpm && r.proximaFacturaIpm < hoy);
  const q = busqueda.trim().toLowerCase();
  const pendientes = q
    ? pendientesDelMes.filter((r) => (r.od || "").toLowerCase().includes(q) || (r.cliente || "").toLowerCase().includes(q) || (r.tecnico || "").toLowerCase().includes(q))
    : pendientesDelMes;

  const marcarFacturado = async (r) => {
    if (!(await confirmar(`¿Confirmas que ya facturaste la OD ${r.od}?`, { confirmLabel: "Sí, ya facturé", variant: "accent" }))) return;
    const usaAgenda = Array.isArray(r.mesesVisita) && r.mesesVisita.length > 0;
    const proxima = usaAgenda ? r.proximaFacturaIpm : sumarIntervaloFrecuencia(hoy, r.frecuencia);
    setRows((prev) => prev.map((x) => x.id === r.id ? { ...x, ultimaFacturaIpm: hoy, proximaFacturaIpm: proxima } : x));
    supabase.from("ordenes_trabajo").update(odPatchToDb({ ultimaFacturaIpm: hoy, proximaFacturaIpm: proxima })).eq("id", r.id).then();
    supabase.from("facturas_ipm").insert({ od_id: r.id, fecha_facturada: hoy }).then();
  };

  return (
    <Card title="IPM a facturar este mes" action={pendientesDelMes.length > 0 ? <Badge color={atrasadas.length ? T.red : T.amber} soft={atrasadas.length ? T.redSoft : T.amberSoft}>{pendientesDelMes.length}</Badge> : null}>
      {pendientesDelMes.length > 0 && (
        <div style={{ position: "relative", marginBottom: 10 }}>
          <Search size={14} style={{ position: "absolute", left: 10, top: "50%", transform: "translateY(-50%)", color: T.gray }} />
          <input
            style={{ ...inputStyle, paddingLeft: 30, fontSize: 12.5 }}
            placeholder="Buscar por OD, cliente o técnico..."
            value={busqueda}
            onChange={(e) => setBusqueda(e.target.value)}
          />
        </div>
      )}
      {pendientesDelMes.length === 0 ? (
        <div style={{ color: T.gray, fontSize: 13 }}>No hay IPM pendientes de facturar este mes.</div>
      ) : pendientes.length === 0 ? (
        <div style={{ color: T.gray, fontSize: 13 }}>Ningún resultado para "{busqueda}".</div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {pendientes.map((r) => {
            const usaAgenda = Array.isArray(r.mesesVisita) && r.mesesVisita.length > 0;
            const estado = estadoFacturacionIpm(r, hoy);
            return (
              <div key={r.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "8px 10px", background: T.bg, borderRadius: 8, gap: 8 }}>
                <div>
                  <div style={{ fontWeight: 700, fontSize: 13 }}>{r.od} — {r.cliente}</div>
                  <div style={{ fontSize: 12, color: T.inkSoft }}>
                    {usaAgenda ? `Mes a facturar: ${formatMesAno(hoy.slice(0, 7))}` : `Frecuencia: ${r.frecuencia || "—"}`}{r.tecnico ? ` · ${r.tecnico}` : ""}
                  </div>
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <Badge color={estado.colorTxt} soft={estado.colorFondo}>
                    <Dot color={estado.colorTxt} />
                    {estado.etiqueta}
                  </Badge>
                  {puedeMarcar && (
                    <Btn small variant="ghost" onClick={() => marcarFacturado(r)}><Check size={13} /> Marcar facturado</Btn>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </Card>
  );
}

// OD Correctivos de IPM: en cuanto un trabajo queda "Completado" y sigue
// "Sin facturar", aparece aquí para que no se olvide facturarlo. Al marcarlo
// facturado sale de la lista (y en OD Correctivos queda como "Facturado").
function FacturacionCorrectivosCard() {
  const [rows, setRows] = useClientesArea("inspecciones");
  const currentUser = useContext(CurrentUserContext);
  const confirmar = useContext(ConfirmContext);
  const puedeMarcar = currentUser?.categoria === "admin" || currentUser?.categoria === "asistente";
  const [busqueda, setBusqueda] = useState("");
  const porFacturar = rows
    .filter((r) => (r.tipoOD || "Normal") === "Correctivo" && (r.progreso || "Pendiente") === "Completado" && (r.facturado || "Sin facturar") !== "Facturado")
    .sort((a, b) => String(a.fechaAprobacion || a.created_at || "").localeCompare(String(b.fechaAprobacion || b.created_at || "")) || (a.od || "").localeCompare(b.od || ""));
  const q = busqueda.trim().toLowerCase();
  const lista = q ? porFacturar.filter((r) => [r.od, r.cliente, r.tecnico, r.equiposCorrectivo].some((x) => String(x || "").toLowerCase().includes(q))) : porFacturar;
  const marcarFacturado = async (r) => {
    if (!(await confirmar(`¿Confirmas que ya facturaste el correctivo ${r.od}?`, { confirmLabel: "Sí, ya facturé", variant: "accent" }))) return;
    setRows((prev) => prev.map((x) => (x.id === r.id ? { ...x, facturado: "Facturado" } : x)));
    supabase.from("ordenes_trabajo").update({ facturado: "Facturado" }).eq("id", r.id).then();
  };
  return (
    <Card title="Correctivos IPM completados por facturar" action={porFacturar.length > 0 ? <Badge color={T.red} soft={T.redSoft}>{porFacturar.length}</Badge> : null}>
      {porFacturar.length > 0 && (
        <div style={{ position: "relative", marginBottom: 10 }}>
          <Search size={14} style={{ position: "absolute", left: 10, top: "50%", transform: "translateY(-50%)", color: T.gray }} />
          <input style={{ ...inputStyle, paddingLeft: 30, fontSize: 12.5 }} placeholder="Buscar por OD, cliente, técnico o equipo..." value={busqueda} onChange={(e) => setBusqueda(e.target.value)} />
        </div>
      )}
      {porFacturar.length === 0 ? (
        <div style={{ color: T.gray, fontSize: 13 }}>No hay correctivos completados pendientes de facturar.</div>
      ) : lista.length === 0 ? (
        <div style={{ color: T.gray, fontSize: 13 }}>Ningún resultado para "{busqueda}".</div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {lista.map((r) => (
            <div key={r.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "8px 10px", background: T.bg, borderRadius: 8, gap: 8, flexWrap: "wrap" }}>
              <div style={{ minWidth: 0 }}>
                <div style={{ fontWeight: 700, fontSize: 13 }}>{r.od} — {r.cliente}</div>
                <div style={{ fontSize: 12, color: T.inkSoft }}>
                  {r.fechaAprobacion ? `Aprobado: ${r.fechaAprobacion}` : "Correctivo"}{r.tecnico ? ` · ${r.tecnico}` : ""}{r.equiposCorrectivo ? ` · ${r.equiposCorrectivo}` : ""}
                </div>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <Badge color={T.green} soft={T.greenSoft}><Dot color={T.green} />Completado</Badge>
                <Badge color={T.red} soft={T.redSoft}>Sin facturar</Badge>
                {puedeMarcar && <Btn small variant="ghost" onClick={() => marcarFacturado(r)}><Check size={13} /> Marcar facturado</Btn>}
              </div>
            </div>
          ))}
        </div>
      )}
    </Card>
  );
}

// ===== Tipo de cambio del día (colones por dólar, venta) =====
// Tipo de cambio de REFERENCIA del Banco Central de Costa Rica (venta).
// Se toma una vez al día de /api/tc (Vercel → servicio web del BCCR; respaldo:
// Hacienda, que publica el mismo dato del BCCR); si no, el último guardado.
const TC_RESPALDO = 505;
const hoyCR = () => new Date().toLocaleDateString("en-CA");
function leerTCGuardado() { try { return JSON.parse(localStorage.getItem("tcDia") || "null"); } catch (e) { return null; } }
let TC_PROMESA = null;
function obtenerTipoCambio() {
  const hoy = hoyCR(), g = leerTCGuardado();
  if (g && g.dia === hoy && g.venta > 0) return Promise.resolve(g);
  if (TC_PROMESA) return TC_PROMESA;
  const fuentes = [
    async () => { const r = await fetch("/api/tc"); if (!r.ok) throw new Error("api"); const j = await r.json(); return { venta: Number(j.venta), compra: Number(j.compra), fecha: j.fecha, fuente: j.fuente || "Banco Central de Costa Rica" }; },
    async () => { const r = await fetch("https://api.hacienda.go.cr/indicadores/tc/dolar"); if (!r.ok) throw new Error("hacienda"); const j = await r.json(); return { venta: Number(j && j.venta && j.venta.valor), compra: Number(j && j.compra && j.compra.valor), fecha: j && j.venta && j.venta.fecha, fuente: "BCCR (referencia, venta) vía Hacienda" }; },
  ];
  TC_PROMESA = (async () => {
    for (const f of fuentes) {
      try { const x = await f(); if (x.venta > 0) { const out = { ...x, dia: hoy }; try { localStorage.setItem("tcDia", JSON.stringify(out)); } catch (e) { /* nada */ } return out; } } catch (e) { /* siguiente fuente */ }
    }
    if (g && g.venta > 0) return { ...g, viejo: true };
    return { venta: TC_RESPALDO, fecha: "", fuente: "valor de respaldo (no se pudo consultar)", dia: hoy, respaldo: true };
  })();
  TC_PROMESA.finally(() => { setTimeout(() => { TC_PROMESA = null; }, 60000); });
  return TC_PROMESA;
}
function useTipoCambio() {
  const [tc, setTc] = useState(() => { const g = leerTCGuardado(); return g && g.venta > 0 ? g : { venta: TC_RESPALDO, fuente: "consultando…" }; });
  useEffect(() => { let vivo = true; obtenerTipoCambio().then((x) => { if (vivo) setTc(x); }); return () => { vivo = false; }; }, []);
  return tc;
}
// Monto de una solicitud en dólares (si está en colones se divide entre su tipo de cambio)
const aUSD = (monto, moneda, tcFila, tcHoy) => (moneda === "CRC" ? (Number(monto) || 0) / (Number(tcFila) || Number(tcHoy) || TC_RESPALDO) : Number(monto) || 0);
const fmtCRC = (v) => "₡" + Math.round(Number(v) || 0).toLocaleString("es-CR");
const tcTexto = (tc) => "₡" + (Number(tc.venta) || TC_RESPALDO).toLocaleString("es-CR", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + (tc.fecha ? " (" + String(tc.fecha).slice(0, 10) + ")" : "") + (tc.respaldo ? " · respaldo" : tc.viejo ? " · último disponible" : "");

function ResumenCotizacionesCard() {
  const [rows, setRows] = useState([]);
  useEffect(() => {
    const cargar = async () => {
      const { data } = await supabase.from("cotizaciones").select("*");
      if (data) setRows(data);
    };
    cargar();
    const intervalo = setInterval(cargar, 20000); // se refresca sola cada 20s
    return () => clearInterval(intervalo);
  }, []);
  const tc = useTipoCambio();
  const total = rows.length;
  const conOC = rows.filter((r) => r.actividad === "Con OC").length;
  const tasaConversion = total > 0 ? Math.round((conOC / total) * 1000) / 10 : 0;
  // Montos en colones se convierten a dólares con su tipo de cambio (o el de hoy)
  const usdDe = (r) => aUSD(r.monto, r.moneda, r.tipo_cambio, tc.venta);
  const pipelineAbierto = rows.filter((r) => r.actividad === "Seguimiento").reduce((s, r) => s + usdDe(r), 0);
  const valorGanado = rows.filter((r) => r.actividad === "Con OC").reduce((s, r) => s + usdDe(r), 0);
  const enColones = rows.filter((r) => r.moneda === "CRC").length;

  return (
    <Card title="Cotizaciones — conversión y pipeline">
      <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 14 }}>
        <div style={{ background: T.blueSoft, borderRadius: 10, padding: 14 }}>
          <div style={{ fontSize: 22, fontWeight: 800, color: T.blue }}>{tasaConversion}%</div>
          <div style={{ fontSize: 12, color: T.inkSoft }}>Tasa de conversión ({conOC} de {total} → Con OC)</div>
        </div>
        <div style={{ background: T.amberSoft, borderRadius: 10, padding: 14 }}>
          <div style={{ fontSize: 22, fontWeight: 800, color: T.amber }}>{fmtMoney(pipelineAbierto)}</div>
          <div style={{ fontSize: 12, color: T.inkSoft }}>Valor del pipeline abierto (en Seguimiento)</div>
          <div style={{ fontSize: 11.5, color: T.inkSoft, marginTop: 2 }}>≈ {fmtCRC(pipelineAbierto * tc.venta)}</div>
        </div>
        <div style={{ background: T.greenSoft, borderRadius: 10, padding: 14 }}>
          <div style={{ fontSize: 22, fontWeight: 800, color: T.green }}>{fmtMoney(valorGanado)}</div>
          <div style={{ fontSize: 12, color: T.inkSoft }}>Valor ganado (Con OC)</div>
          <div style={{ fontSize: 11.5, color: T.inkSoft, marginTop: 2 }}>≈ {fmtCRC(valorGanado * tc.venta)}</div>
        </div>
      </div>
      <div style={{ fontSize: 11.5, color: T.inkSoft, marginTop: 10 }}>Montos en dólares. {enColones ? enColones + " cotización(es) en colones se convierten con su tipo de cambio. " : ""}Tipo de cambio de hoy (venta): <b>{tcTexto(tc)}</b> · {tc.fuente}</div>
    </Card>
  );
}

// =====================================================================
// COTIZACIÓN EN PROCESO (Cotizaciones → pestaña solo admin y asistente)
// Módulo Cotizador A&D de Anthony: mano de obra, viáticos, renta de equipos,
// materiales, márgenes y descarga del machote Excel. Todo queda dentro de
// esta función para no chocar con nombres del resto de la app.
// La configuración (salarios, overhead, catálogos) vive en Supabase en la
// tabla cotizador_config, que solo se lee/guarda con funciones que revisan
// el usuario (ver cotizador_supabase.sql).
// =====================================================================
const COTZ_CSS = `.cotz{--bg:#F3F5F7;--surface:#FFFFFF;--surface2:#F7F8FA;--line:#E1E6EB;--fg:#101826;--muted:#5B6572;
  --red:#E86A2C;--red-hover:#CF5A20;--red-text:#C9541C;--red-soft:#FFE4D3;
  --slate:#1F3A5F;--slate-hover:#182F4D;--sky:#EDEFF2;--in-line:#E1E6EB;
  --ok-bg:#DEF2E8;--ok-fg:#2E7D5B;--err-bg:#FBE4E4;--err-fg:#C13E3E;--warn-bg:#FBEBCB;--warn-fg:#8A5C00;
  color:var(--fg);font-family:inherit;font-size:13.5px}
.cotz, .cotz *{box-sizing:border-box}
.cotz button,.cotz input,.cotz select{font:inherit}
.cotz :focus-visible{outline:2px solid var(--red);outline-offset:2px}
.cotz .wrap{padding-inline:0}
.cotz .topinfo{background:var(--sky);border-radius:10px;font-size:12px;color:var(--muted);margin-bottom:10px}
.cotz .topinfo .wrap{display:flex;flex-wrap:wrap;gap:4px 16px;justify-content:space-between;padding:7px 12px}
.cotz .topinfo strong{color:var(--fg)}
.cotz .dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:6px;vertical-align:middle}
.cotz .brand{background:var(--slate);color:#fff;border-radius:12px}
.cotz .brand .wrap{display:flex;flex-wrap:wrap;gap:10px 14px;align-items:center;justify-content:space-between;padding:12px 16px}
.cotz .btitle{font-weight:800;font-size:16px;letter-spacing:-.2px;line-height:1.2}
.cotz .bsub{font-size:12px;color:rgba(255,255,255,.75)}
.cotz .hbtns{display:flex;flex-wrap:wrap;gap:8px;align-items:center}
.cotz .btn{display:inline-flex;align-items:center;gap:6px;min-height:36px;padding:8px 14px;border-radius:9px;border:1px solid transparent;font-weight:600;font-size:13px;cursor:pointer;white-space:nowrap;transition:filter .15s}
.cotz .btn:hover{filter:brightness(.94)}
.cotz .btn svg{flex:none;width:16px;height:16px}
.cotz .btn-ghost{background:rgba(255,255,255,.12);color:#fff;border-color:rgba(255,255,255,.35)}
.cotz .btn-dark{background:var(--slate);color:#fff}
.cotz .brand .btn-dark{background:#fff;color:var(--slate)}
.cotz .btn-red{background:var(--red);color:#fff}
.cotz .btn-line{background:transparent;color:var(--slate);border-color:var(--line)}
.cotz .btn[disabled]{opacity:.5;cursor:not-allowed;filter:none}
.cotz .gear{width:36px;padding:0;justify-content:center}
.cotz .gear svg{width:19px;height:19px}
.cotz .main{display:flex;flex-wrap:wrap;gap:14px;align-items:flex-start;padding-block:14px 4px}
.cotz .nav{flex:1 1 100%;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:6px;display:flex;flex-direction:row;flex-wrap:wrap;gap:4px}
.cotz .nav .navbtn{flex:1 1 150px;width:auto}
.cotz .navbtn{display:flex;align-items:center;gap:10px;width:100%;padding:9px 10px;border:0;border-radius:9px;background:transparent;color:var(--fg);cursor:pointer;text-align:left;min-height:46px}
.cotz .navbtn:hover{background:var(--surface2)}
.cotz .navbtn.on{background:var(--red);color:#fff}
.cotz .badge{display:inline-flex;align-items:center;justify-content:center;width:24px;height:24px;border-radius:50%;background:var(--sky);color:var(--slate);font-weight:700;font-size:12px;flex:none}
.cotz .navbtn.on .badge{background:#fff;color:var(--red)}
.cotz .navname{font-weight:600;display:block;font-size:13px}
.cotz .navsub{font-size:11.5px;color:var(--muted);font-variant-numeric:tabular-nums}
.cotz .navbtn.on .navsub{color:rgba(255,255,255,.85)}
.cotz .work{flex:999 1 520px;min-width:0;background:var(--surface);border:1px solid var(--line);border-radius:14px;overflow:hidden}
.cotz .workhead{padding:14px 18px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:baseline;flex-wrap:wrap;gap:6px}
.cotz h1,.cotz h2,.cotz h3{text-wrap:balance}
.cotz .workhead h1{margin:0;font-size:16px;font-weight:800;letter-spacing:-.2px;color:var(--fg)}
.cotz .hint{font-size:12.5px;color:var(--muted)}
.cotz .workbody{padding:18px}
.cotz .side{flex:1 1 270px;max-width:330px;min-width:250px;display:flex;flex-direction:column;gap:12px}
.cotz .card{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:14px 16px}
.cotz .dark{background:var(--slate);color:#fff;border-radius:14px;padding:16px}
.cotz .redcard{background:var(--red);color:#fff;border-radius:14px;padding:14px 16px}
.cotz .kicker{font-size:11px;letter-spacing:.06em;text-transform:uppercase;font-weight:700}
.cotz .bignum{font-weight:800;letter-spacing:-.5px;line-height:1.15;font-variant-numeric:tabular-nums}
.cotz .ctitle{font-size:14px;font-weight:700;margin:0 0 6px;color:var(--fg)}
.cotz .kv{display:flex;justify-content:space-between;gap:10px;padding:6px 0;border-bottom:1px solid var(--line);font-size:13px;font-variant-numeric:tabular-nums}
.cotz .kv:last-child{border-bottom:0}
.cotz .kv span:first-child{color:var(--muted)}
.cotz .dark .kv span:first-child{color:rgba(255,255,255,.75)}
.cotz .kv > :last-child{white-space:nowrap}
.cotz .tblbox{overflow-x:auto;border:1px solid var(--line);border-radius:10px}
.cotz table{width:100%;border-collapse:collapse;font-size:13px;font-variant-numeric:tabular-nums}
.cotz th{background:var(--surface2);color:var(--muted);font-weight:700;text-align:left;padding:8px 10px;font-size:11px;letter-spacing:.04em;text-transform:uppercase;white-space:nowrap;border-bottom:1px solid var(--line)}
.cotz td{padding:6px 10px;border-top:1px solid var(--line);vertical-align:middle;white-space:nowrap}
.cotz tbody tr:first-child td{border-top:0}
.cotz .r{text-align:right}
.cotz .strong{font-weight:700}
.cotz .num{width:76px;padding:7px 9px;border:1px solid var(--line);border-radius:8px;font-size:13.5px;text-align:right;background:#fff;color:var(--fg);font-weight:600;min-height:34px;font-variant-numeric:tabular-nums;outline:none}
.cotz .num:focus,.cotz .txt:focus,.cotz .sel:focus{border-color:var(--slate)}
.cotz .num:disabled,.cotz .txt:disabled{background:var(--surface2);color:var(--muted)}
.cotz .num.wide{width:130px}
.cotz .main.ancho .work{flex-basis:100%}
.cotz .main.ancho .side{flex:1 1 100%;max-width:none;flex-direction:row;flex-wrap:wrap}
.cotz .main.ancho .side > *{flex:1 1 240px}
.cotz .desg{margin-bottom:14px}
.cotz .desg-h{display:flex;justify-content:space-between;flex-wrap:wrap;gap:6px;font-size:13.5px;font-weight:800;color:var(--slate);margin:0 0 6px;padding:7px 10px;background:var(--sky);border-radius:8px}
.cotz .desg-h span:last-child{font-weight:500;color:var(--muted);font-size:12.5px}
.cotz .desg-h strong{color:var(--red-text)}
.cotz .editbar{display:flex;flex-wrap:wrap;gap:10px;align-items:center;justify-content:space-between;margin-top:10px;padding:10px 14px;border-radius:12px;background:var(--warn-bg);color:var(--warn-fg);font-size:13px;border:1px solid #F0C36D}
.cotz .embudo{display:flex;flex-wrap:wrap;align-items:stretch;gap:8px;margin-top:10px}
.cotz .emb-c{flex:1 1 170px;border:1px solid var(--line);border-radius:12px;padding:12px 14px;background:#fff}
.cotz .emb-c.gan{background:var(--ok-bg);border-color:#A8D5AA}
.cotz .emb-t{font-size:12px;font-weight:700;color:var(--muted)}
.cotz .emb-n{font-size:28px;font-weight:800;line-height:1.1;font-variant-numeric:tabular-nums}
.cotz .emb-m{font-size:14px;font-weight:700;color:var(--slate);font-variant-numeric:tabular-nums}
.cotz .emb-s{font-size:11.5px;color:var(--muted)}
.cotz .emb-f{flex:0 0 auto;display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:11.5px;color:var(--muted);padding:0 4px}
.cotz .emb-f span{font-size:16px;font-weight:800;color:var(--red-text)}
.cotz .emb-f::after{content:'→';font-size:18px;color:var(--muted);line-height:1}
.cotz .kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;margin-top:12px}
.cotz .kpi{border:1px solid var(--line);border-radius:10px;padding:9px 12px;background:#fff}
.cotz .kpi-t{font-size:11.5px;font-weight:700;color:var(--muted)}
.cotz .kpi-v{font-size:20px;font-weight:800;color:var(--fg);font-variant-numeric:tabular-nums;line-height:1.2}
.cotz .kpi-s{font-size:11px;color:var(--muted)}
.cotz .charts{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:12px;margin-top:12px}
.cotz .chartbox{border:1px solid var(--line);border-radius:12px;padding:10px 12px 8px;background:#fff}
.cotz .chart-t{font-size:13px;font-weight:700;margin-bottom:4px}
.cotz .chart-vacio{height:200px;display:flex;align-items:center;justify-content:center;color:var(--muted);font-size:12.5px}
.cotz .chart-ley{display:flex;flex-wrap:wrap;gap:12px;font-size:11.5px;color:var(--muted);margin-top:4px}
.cotz .chart-ley i{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:5px;vertical-align:-1px}
.cotz .txt.fecha{min-height:30px;padding:4px 6px;font-size:12.5px;width:132px}
.cotz .num.verde{background:#E9F6EA;border-color:#A8D5AA}
.cotz .num.auto::placeholder{color:#3F7A47;opacity:.75}
.cotz .calc{font-weight:600;font-variant-numeric:tabular-nums;color:var(--fg)}
.cotz .fx{display:block;font-size:11px;font-weight:400;color:var(--muted)}
.cotz tr.apagada td{color:var(--muted)}
.cotz tr.apagada td.strong{font-weight:600}
.cotz tr.subt td{background:var(--surface2);font-weight:700}
.cotz .verdetxt{background:#E9F6EA;border:1px solid #A8D5AA;border-radius:4px;padding:0 5px;font-weight:700;color:#2E6B35}
.cotz .num.full{width:100%}
.cotz .dark .num{background:rgba(255,255,255,.12);border-color:rgba(255,255,255,.3);color:#fff}
.cotz .txt{width:100%;padding:8px 10px;border:1px solid var(--line);border-radius:8px;font-size:13.5px;background:#fff;color:var(--fg);min-height:36px;outline:none}
.cotz .txt.cell{min-height:34px;font-size:13px;min-width:200px}
.cotz .txt.short{min-width:70px;width:90px}
.cotz .sel{padding:8px 10px;border:1px solid var(--line);border-radius:8px;font-size:13.5px;background:#fff;color:var(--fg);min-height:36px;outline:none}
.cotz .field{display:flex;flex-direction:column;gap:5px;font-size:12px;font-weight:700;color:var(--muted)}
.cotz .grid2{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px 18px}
.cotz .grid3{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px}
.cotz .sec{margin:22px 0 8px;font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;font-weight:700}
.cotz .sec:first-child{margin-top:0}
.cotz .tile{background:var(--slate);color:#fff;border-radius:12px;padding:12px 14px}
.cotz .tile .bignum{font-size:28px}
.cotz .tile .kicker{color:rgba(255,255,255,.75)}
.cotz .tabs{display:inline-flex;gap:8px;margin-bottom:14px;flex-wrap:wrap}
.cotz .tab{padding:6px 12px;border:1px solid var(--line);background:transparent;color:var(--slate);font-weight:600;font-size:12.5px;cursor:pointer;border-radius:9px;min-height:32px}
.cotz .tab.on{background:var(--red);color:#fff;border-color:var(--red)}
.cotz .rm{border:0;background:transparent;color:var(--muted);cursor:pointer;width:32px;height:32px;border-radius:8px;display:inline-flex;align-items:center;justify-content:center}
.cotz .rm svg{width:16px;height:16px}
.cotz .rm:hover{background:var(--err-bg);color:var(--err-fg)}
.cotz .note{font-size:12.5px;color:var(--muted);margin:10px 0 0;line-height:1.5}
.cotz .banner{padding:10px 14px;border-radius:10px;font-size:13px;line-height:1.5;margin-bottom:14px}
.cotz .b-info{background:var(--sky);color:var(--fg)}
.cotz .b-ok{background:var(--ok-bg);color:var(--ok-fg)}
.cotz .b-err{background:var(--err-bg);color:var(--err-fg)}
.cotz .b-warn{background:var(--warn-bg);color:var(--warn-fg)}
.cotz .foot{display:flex;justify-content:space-between;gap:10px;margin-top:22px;padding-top:14px;border-top:1px solid var(--line)}
.cotz .total{margin-top:12px;text-align:right;font-size:14px}
.cotz .total strong{color:var(--red-text);font-size:18px;font-variant-numeric:tabular-nums}
.cotz .cmp{display:grid;grid-template-columns:120px repeat(5,minmax(112px,1fr));min-width:700px;border-radius:10px;overflow:hidden;border:1px solid var(--line)}
.cotz .mc{padding:8px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:center;font-size:13px;font-variant-numeric:tabular-nums}
.cotz .mc.lab{justify-content:flex-start;font-weight:700;background:var(--surface2);color:var(--muted);font-size:12px}
.cotz .mc.on{background:var(--red-soft);color:var(--red-text);font-weight:700}
.cotz .use{border:1px solid var(--line);background:#fff;color:var(--slate);border-radius:8px;padding:5px 12px;cursor:pointer;min-height:30px;font-weight:600;font-size:12.5px}
.cotz .mc.on .use{background:var(--red);color:#fff;border-color:var(--red)}
.cotz input[type=range]{accent-color:var(--red);width:100%}
.cotz .hidefile{position:absolute;width:1px;height:1px;opacity:0;overflow:hidden}
.cotz .sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.cotz .addrow{display:flex;flex-wrap:wrap;gap:10px;align-items:center;justify-content:space-between;margin-top:12px}
.cotz .ovl{position:fixed;inset:0;z-index:60;background:var(--bg);overflow:auto;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
.cotz .ovl .wrap{max-width:1300px;margin:0 auto;padding-inline:16px}
.cotz .ovlhead{background:var(--slate);color:#fff;position:sticky;top:0;z-index:2}
.cotz .ovlhead .wrap{display:flex;flex-wrap:wrap;gap:10px;align-items:center;justify-content:space-between;padding-block:10px}
.cotz .ovlhead h2{margin:0;font-size:16px;font-weight:800;display:flex;align-items:center;gap:8px}
.cotz .ovlhead h2 svg{width:19px;height:19px}
.cotz .cfgmain{display:flex;flex-wrap:wrap;gap:14px;align-items:flex-start;padding-block:16px 100px}
.cotz .cfgnav{flex:1 1 210px;max-width:250px;min-width:200px;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:8px;display:flex;flex-direction:column;gap:3px}
.cotz .cfgnav .navbtn{min-height:40px}
.cotz .cfgbody{flex:999 1 520px;min-width:0;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:18px}
.cotz .cfgbody h3{margin:0 0 4px;font-size:16px;font-weight:800}
.cotz .savebar{position:fixed;left:0;right:0;bottom:0;z-index:3;background:var(--surface);border-top:1px solid var(--line);box-shadow:0 -2px 8px rgba(0,0,0,.06);padding-bottom:env(safe-area-inset-bottom,0px)}
.cotz .savebar .wrap{display:flex;flex-wrap:wrap;gap:10px;align-items:center;justify-content:space-between;padding-block:10px}
.cotz .drop{border:2px dashed var(--line);border-radius:12px;padding:16px;display:flex;flex-wrap:wrap;gap:14px;align-items:center;justify-content:space-between;background:var(--surface2)}
.cotz .check{display:flex;gap:10px;align-items:flex-start;font-size:13px;margin-top:12px;cursor:pointer}
.cotz .check input{width:18px;height:18px;margin-top:1px;accent-color:var(--red)}
.cotz .toast{position:fixed;left:50%;bottom:calc(20px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);z-index:70;background:var(--slate);color:#fff;padding:10px 16px;border-radius:10px;box-shadow:0 6px 20px rgba(0,0,0,.25);font-size:13px;max-width:calc(100% - 32px)}
.cotz .origenbox{background:var(--surface2);border:1px solid var(--line);border-radius:12px;padding:12px 14px;margin-bottom:16px}
.cotz .tab.big{min-height:40px;padding:8px 16px;font-size:13.5px}
.cotz .finbox{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin-top:16px;padding:14px 16px;border-radius:12px;background:var(--red-soft);border:1px solid #F5C4A8}
.cotz .origenes{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px;margin-top:10px}
.cotz .orig{display:flex;flex-direction:column;align-items:flex-start;gap:1px;text-align:left;border:1px solid var(--line);background:#fff;border-radius:10px;padding:8px 12px;cursor:pointer}
.cotz .orig.on{border-color:var(--red);background:var(--red-soft)}
.cotz .o-n{font-size:12px;font-weight:700;color:var(--muted)}
.cotz .o-v{font-size:16px;font-weight:800;color:var(--fg);font-variant-numeric:tabular-nums}
.cotz .o-c{font-size:11.5px;color:var(--muted)}
.cotz .chip{display:inline-block;font-size:11.5px;font-weight:700;border-radius:999px;padding:2px 9px;background:var(--sky);color:var(--slate)}
.cotz .chip.vend{background:var(--red-soft);color:var(--red-text)}
.cotz .nuevapanel{margin-top:10px;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:14px 16px}
.cotz .np-t{font-weight:800;font-size:14px;margin-bottom:10px}
.cotz .np-t span{font-weight:400;color:var(--muted);font-size:12.5px}
.cotz .np-ops{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px}
.cotz .np-op{border:1px solid var(--line);border-radius:12px;padding:12px 14px;display:flex;flex-direction:column;align-items:flex-start;gap:6px}
.cotz .np-h{font-weight:700;font-size:13.5px}
.cotz .np-d{font-size:12.5px;color:var(--muted);margin-bottom:4px}
.cotz .solref{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:6px 16px;font-size:12.5px}
.cotz .solref span{display:block;font-size:11px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.03em}
@media (max-width:640px){.cotz .side,.cotz .cfgnav{max-width:none}.cotz .nav .navbtn{flex:1 1 130px}}
@media (prefers-reduced-motion:reduce){.cotz, .cotz *{transition:none!important;animation:none!important}}
`;
