  30: { n: 'Cable 2x16 (Incendio-Intemperie)', d: 413, u: 'Carrucha (305m)', tipo: 'in', sug: 'J30' },
  31: { n: 'Cable 2x14 (Incendio-Intemperie)', d: 624, u: 'Carrucha (305m)', tipo: 'in' },
  32: { n: 'Cable 4x18 (Incendio)', d: 381, u: 'Carrucha (305m)', tipo: 'in' },
